# Find connected components of 2s
from collections import deque

def get_components(grid):
    rows, cols = len(grid), len(grid[0])
    visited = set()
    components = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 2 and (r,c) not in visited:
                comp = [(r,c)]
                q = deque([(r,c)])
                while q:
                    curr_r, curr_c = q.popleft()
                    for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
                        nr, nc = curr_r + dr, curr_c + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if grid[nr][nc] == 2 and (nr,nc) not in visited:
                                visited.add((nr,nc))
                                comp.append((nr,nc))
                                q.append((nr,nc))
                visited.add((r,c))
                components.append(comp)

    return components

components = get_components(input_grid)
print(f"Connected components of 2s: {len(components)}")
for i, comp in enumerate(components):
    print(f"Component {i}: {sorted(comp)}")

