from collections import deque

def compute_min_distance(grid):
    rows, cols = len(grid), len(grid[0])
    dist = [[999]*cols for _ in range(rows)]
    q = deque()

    # Initialize with 2 positions at distance 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 2:
                dist[r][c] = 0
                q.append((r,c))

    # BFS to find minimum distance from any 2
    while q:
        r, c = q.popleft()
        for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < rows and 0 <= nc < cols and dist[nr][nc] > dist[r][c] + 1:
                dist[nr][nc] = dist[r][c] + 1
                q.append((nr, nc))

    return dist

distances = compute_min_distance(input_grid)
